import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.uPk2SrVb.js";const d=JSON.parse('{"title":"2026-11-04 Agent 核心研究与竞品动态","description":"企业化治理、原生 worker 与协作恢复；28 组事实观察、6 组研究分析，保留发行和验证边界。","frontmatter":{"title":"2026-11-04 Agent 核心研究与竞品动态","description":"企业化治理、原生 worker 与协作恢复；28 组事实观察、6 组研究分析，保留发行和验证边界。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-04.md","filePath":"zh/runtime/daily-intelligence/2026-11-04.md","lastUpdated":null}'),n={name:"zh/runtime/daily-intelligence/2026-11-04.md"};function s(l,e,i,p,g,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-11-04-agent-核心研究与竞品动态" tabindex="-1">2026-11-04 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-04-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-04 Agent 核心研究与竞品动态&quot;">​</a></h1><p><strong>核心结论：企业化 Agent 治理正在具体化为“主体与 turn 绑定、协作任务语义、独立执行证据、可核对的恢复责任”。</strong> 本轮尤其值得关注 OpenAI SDK 原生 harness 预览、仍在评审的 worker 监督/副作用恢复、AG2 事件树正式合入、Paradev 的一人一 turn，以及记忆/SOP 的岗位边界。不同项目的变化支持这些研究方向，尚不能证明普适方案或 CodeFlowMu 本地适用性。</p><p>按已确认的两层规范交付：先列 <strong>28 组事实观察 O1–O28</strong>，再给 <strong>6 组分析 A1–A6</strong>。分析引用观察，不重复计作新增。另保留历史协议候选 C1，明确不计本轮新增。</p><p>实际起点 <strong>2026-11-04 16:42:35 Asia/Shanghai（08:42:35 UTC）</strong>；常规窗口从上次起点 <strong>2026-11-03 02:03:00 UTC</strong> 开始。commit 查询使用各来源成功基线并截止本轮起点；PR/Issue 状态以各项核查时间为准。最新 main Registry 仍为 <strong>47 位研究者</strong>，blob <code>8d97df65269aa2b4accd1366d1b71319f99c6efd</code>。人物是主体，仓库是证据入口，不把仓库贡献归成某位研究者的新论文。</p><h2 id="第一层-事实观察" tabindex="-1">第一层：事实观察 <a class="header-anchor" href="#第一层-事实观察" aria-label="Permalink to &quot;第一层：事实观察&quot;">​</a></h2><h3 id="o1-openai-agents-sdk-原生-harness-预览交付" tabindex="-1">O1. OpenAI Agents SDK：原生 harness 预览交付 <a class="header-anchor" href="#o1-openai-agents-sdk-原生-harness-预览交付" aria-label="Permalink to &quot;O1. OpenAI Agents SDK：原生 harness 预览交付&quot;">​</a></h3><p><strong>状态：Python v0.24.0-alpha.6 / JS v0.22.0-alpha.1 RELEASED (prerelease)</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>Python 预览扩展捕获 Turn、排队/steer/cancel、LocalStorage、portable state、手工工具请求与工具策略；恢复使用当前应用工具、凭证和策略，不能扩大 session 初始授权。LocalStorage 不支持 portable checkpoint 导出。JS 首次以 alpha 引入内嵌 Codex harness，提供三平台 starter。Python wheels 支持指定 Linux x64、Apple Silicon、Windows x64；JS starter 要求 Node 24。均为 MIT 仓库，预览 API 与平台限制需逐版核对。</p><p><strong>分析去向与研究价值：A2、A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/openai/openai-agents-python/releases/tag/v0.24.0-alpha.6" target="_blank" rel="noreferrer">v0.24.0-alpha.6</a> · <a href="https://github.com/openai/openai-agents-js/releases/tag/v0.22.0-alpha.1" target="_blank" rel="noreferrer">v0.22.0-alpha.1</a></p><h3 id="o2-原生-worker-监督与不确定调用恢复仍在评审" tabindex="-1">O2. 原生 worker 监督与不确定调用恢复仍在评审 <a class="header-anchor" href="#o2-原生-worker-监督与不确定调用恢复仍在评审" aria-label="Permalink to &quot;O2. 原生 worker 监督与不确定调用恢复仍在评审&quot;">​</a></h3><p><strong>状态：Python #5494 #5502 / JS #2122 #2124 OPEN, not merged or released</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>方案包含逐 turn 写目录、精确 steering、执行/指令 receipts、两 worker 独立历史与 effect journal，以及验收后单独发布。工具可能已产生副作用但尚未记录结果时，恢复须先由应用核对 applied/not_applied 并落盘回读，再允许新工作；不承诺通用 exactly-once，也不替应用判断真实效果。冷启动后代恢复等仍有限制。PR 上游实验不等于本地验证，亦不属于 O1 已发行能力。</p><p><strong>分析去向与研究价值：A1、A2、A3、A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/openai/openai-agents-python/pull/5494" target="_blank" rel="noreferrer">#5494</a> · <a href="https://github.com/openai/openai-agents-python/pull/5502" target="_blank" rel="noreferrer">#5502</a> · <a href="https://github.com/openai/openai-agents-js/pull/2122" target="_blank" rel="noreferrer">#2122</a> · <a href="https://github.com/openai/openai-agents-js/pull/2124" target="_blank" rel="noreferrer">#2124</a></p><h3 id="o3-ag2-事件树合入-统一任务生命周期与并发任务归属" tabindex="-1">O3. AG2：事件树合入，统一任务生命周期与并发任务归属 <a class="header-anchor" href="#o3-ag2-事件树合入-统一任务生命周期与并发任务归属" aria-label="Permalink to &quot;O3. AG2：事件树合入，统一任务生命周期与并发任务归属&quot;">​</a></h3><p><strong>状态：#3526 #3576 #3568 MERGED; new stable release inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>昨天 OPEN 的事件树方案现已合入：祖先可观察后代、定向回复与取消，保留原始 usage 和 provenance。普通 invocation 可选择加入统一 Task 生命周期，终态在清理之后发布。并发兄弟任务的 TaskInject 改用 asyncio ContextVar 链及 stream 身份，避免进度/checkpoint 归错任务；直接读取旧 dependency slot 的路径仍保留。上游披露非标准退出顺序等限制，不能推成跨用户隔离已经全面验证。</p><p><strong>分析去向与研究价值：A2。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/ag2ai/ag2/pull/3526" target="_blank" rel="noreferrer">#3526</a> · <a href="https://github.com/ag2ai/ag2/pull/3576" target="_blank" rel="noreferrer">#3576</a> · <a href="https://github.com/ag2ai/ag2/pull/3568" target="_blank" rel="noreferrer">#3568</a></p><h3 id="o4-codex-技能权限实时校验、审批重评与工作负载身份" tabindex="-1">O4. Codex：技能权限实时校验、审批重评与工作负载身份 <a class="header-anchor" href="#o4-codex-技能权限实时校验、审批重评与工作负载身份" aria-label="Permalink to &quot;O4. Codex：技能权限实时校验、审批重评与工作负载身份&quot;">​</a></h3><p><strong>状态：#59278 #59225 #59275 MERGED; stable inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>技能缓存不能在权限撤销或 symlink 替换后继续授权读取；读操作使用匹配的当前 filesystem accessor。Guardian 的批准与拒绝都会在父级授权变化后重校验，失效拒绝不计入拒绝上限。API workload identity 支持 org/project/service account，续期拒绝产品或身份改变，并脱敏 key。当前仅核实合入，不能依据无实质说明的 alpha tag 推断这些能力已正式交付。</p><p><strong>分析去向与研究价值：A1。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/openai/codex/pull/59278" target="_blank" rel="noreferrer">#59278</a> · <a href="https://github.com/openai/codex/pull/59225" target="_blank" rel="noreferrer">#59225</a> · <a href="https://github.com/openai/codex/pull/59275" target="_blank" rel="noreferrer">#59275</a></p><h3 id="o5-kaptein-相关-kyvvu-保护治理执行器自己的状态" tabindex="-1">O5. Kaptein 相关 Kyvvu：保护治理执行器自己的状态 <a class="header-anchor" href="#o5-kaptein-相关-kyvvu-保护治理执行器自己的状态" aria-label="Permalink to &quot;O5. Kaptein 相关 Kyvvu：保护治理执行器自己的状态&quot;">​</a></h3><p><strong>状态：commit 2d9f1e0 on main; claude-code-safety manifest 1.0.7; deployed enforcement NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>镜像提交扩大对 kyvvu 命令、hook 设置和 Claude integration session 文件的保护，并将测试依赖固定为 kyvvu-engine 1.0.0。文档明确：命令正则只覆盖字面写法，alias、变量展开及其他路径拼写仍可绕过，需与结构化/OS 控制共同理解。新增测试代码不等于本轮已运行或证明完整防篡改；这是相关项目工程变化，不是 Kaptein 的新论文。</p><p><strong>分析去向与研究价值：A3、A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/Kyvvu/manifests/commit/2d9f1e0abc189133b8ab9c559543709f0dfc5941" target="_blank" rel="noreferrer">2d9f1e0abc</a></p><h3 id="o6-google-adk-并行分支、恢复屏障、审批事件和空输出评测" tabindex="-1">O6. Google ADK：并行分支、恢复屏障、审批事件和空输出评测 <a class="header-anchor" href="#o6-google-adk-并行分支、恢复屏障、审批事件和空输出评测" aria-label="Permalink to &quot;O6. Google ADK：并行分支、恢复屏障、审批事件和空输出评测&quot;">​</a></h3><p><strong>状态：5 commits on default branch; #7950 #7940 #7908 merged via commits; release inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>Workflow 转发子 Agent 事件时保留子分支，节点及后继保持自己的分支；恢复不再让慢节点把已记录的兄弟节点卡在 replay barrier。委派输出后仍保留文本、错误与工具审批请求，避免等待用户看不见的审批。无事件 turn 仍记录 invocation 参与评测。取消或关闭流也运行 on_model_error 清理，忽略回调的恢复响应，避免把已取消调用恢复成成功。</p><p><strong>分析去向与研究价值：A2。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/google/adk-python/commit/36cb10ddc40884258374f7586438d980bc713d63" target="_blank" rel="noreferrer">36cb10ddc4</a> · <a href="https://github.com/google/adk-python/commit/efec445a46fe637a4ac14bc79df1cb955c4ef96a" target="_blank" rel="noreferrer">efec445a46</a> · <a href="https://github.com/google/adk-python/commit/94eb6c4fc1f3da1eec8b50bca6775bf6ccb7d4ec" target="_blank" rel="noreferrer">94eb6c4fc1</a> · <a href="https://github.com/google/adk-python/commit/27edb4712f5cf1470c77cf515811b99b6ec46014" target="_blank" rel="noreferrer">27edb4712f</a> · <a href="https://github.com/google/adk-python/commit/3565ad3dd0c95125b92e38b02cfe22a77fe5249e" target="_blank" rel="noreferrer">3565ad3dd0</a></p><h3 id="o7-claude-code-2-1-318-审批、凭证与恢复语义修复" tabindex="-1">O7. Claude Code 2.1.318：审批、凭证与恢复语义修复 <a class="header-anchor" href="#o7-claude-code-2-1-318-审批、凭证与恢复语义修复" aria-label="Permalink to &quot;O7. Claude Code 2.1.318：审批、凭证与恢复语义修复&quot;">​</a></h3><p><strong>状态：v2.1.318 RELEASED (stable)</strong><br><strong>发生日期：2026-11-04 (UTC)</strong></p><p>修复慢审批提示被先前键入内容误确认、共享网络 home 写失败却报告信任/注销/MCP 修改成功，以及恢复后已批准命令在错误目录执行。恢复 workflow 不重复执行已完成 Agent；API 错误或停止不再因 mod hook 被报成功。配置/凭证保存更稳健，但发行说明仍披露并发保存可能替换 MCP 配置等边界。属于上游发行事实，非本地实测。</p><p><strong>分析去向与研究价值：A3、A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.318" target="_blank" rel="noreferrer">v2.1.318</a></p><h3 id="o8-langgraph-sdk-0-4-12-昨天合入的断流恢复正式发行" tabindex="-1">O8. LangGraph SDK 0.4.12：昨天合入的断流恢复正式发行 <a class="header-anchor" href="#o8-langgraph-sdk-0-4-12-昨天合入的断流恢复正式发行" aria-label="Permalink to &quot;O8. LangGraph SDK 0.4.12：昨天合入的断流恢复正式发行&quot;">​</a></h3><p><strong>状态：sdk==0.4.12 RELEASED; includes #9554</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>这是昨日 MERGED 到今日 RELEASED 的状态推进：正常断流后可查询 run 状态并按既有 cursor/预算重连。额外 GET 可能重新下载大 input；没有覆盖所有 threadless/无 Location 流。版本还删除 PrioritySettings 的 fairness_weight，属于调用方需检查的接口变化。实现细节不重复算第二项新发明。</p><p><strong>分析去向与研究价值：A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/langchain-ai/langgraph/releases/tag/sdk==0.4.12" target="_blank" rel="noreferrer">sdk==0.4.12</a> · <a href="https://github.com/langchain-ai/langgraph/pull/9554" target="_blank" rel="noreferrer">#9554</a></p><h3 id="o9-openhands-产品发行与-acp-codex-持久会话修复" tabindex="-1">O9. OpenHands：产品发行与 ACP Codex 持久会话修复 <a class="header-anchor" href="#o9-openhands-产品发行与-acp-codex-持久会话修复" aria-label="Permalink to &quot;O9. OpenHands：产品发行与 ACP Codex 持久会话修复&quot;">​</a></h3><p><strong>状态：OpenHands v1.35.0 RELEASED; SDK #6455 MERGED separately, inclusion in product release NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>产品发行说明包含暂停 sandbox 恢复、历史/运行状态及自动化触发编辑等已有修复的交付。另一个更晚的 SDK 修复将 CODEX_HOME 放到会话持久目录，把 auth.json 链接到临时凭证；重启恢复线程而不把凭证存入持久目录。无 symlink 支持时仍回退旧临时 home。上游报告一次真实重启记忆测试，不可推成所有平台已通过；不能把这项晚合入 SDK 修复写进较早产品发行。</p><p><strong>分析去向与研究价值：A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/OpenHands/OpenHands/releases/tag/v1.35.0" target="_blank" rel="noreferrer">v1.35.0</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6455" target="_blank" rel="noreferrer">#6455</a></p><h3 id="o10-langchain-typesafe-初始发行与企业内部-classifier-接入" tabindex="-1">O10. LangChain TypeSafe：初始发行与企业内部 classifier 接入 <a class="header-anchor" href="#o10-langchain-typesafe-初始发行与企业内部-classifier-接入" aria-label="Permalink to &quot;O10. LangChain TypeSafe：初始发行与企业内部 classifier 接入&quot;">​</a></h3><p><strong>状态：langchain-typesafe 0.0.1 RELEASED; #41657 MERGED later, release inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-04 (UTC)</strong></p><p>初始包包含实验性的 AutoMode/ModelRouter middleware 与 invocation-scoped classifier questions。随后合入可传入自定义 classifier，支持企业内部 base_url/transport，不再先构造一个依赖默认 key 的临时 classifier。初始版本号与 PR 正文中的计划切版号不同，应以实际 tag 为准；不把 classifier 判断本身当成企业授权证明。</p><p><strong>分析去向与研究价值：A5。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-typesafe==0.0.1" target="_blank" rel="noreferrer">langchain-typesafe==0.0.1</a> · <a href="https://github.com/langchain-ai/langchain/pull/41657" target="_blank" rel="noreferrer">#41657</a></p><h3 id="o11-langfuse-组织限额、支持人员读取审计与既有修复交付" tabindex="-1">O11. Langfuse：组织限额、支持人员读取审计与既有修复交付 <a class="header-anchor" href="#o11-langfuse-组织限额、支持人员读取审计与既有修复交付" aria-label="Permalink to &quot;O11. Langfuse：组织限额、支持人员读取审计与既有修复交付&quot;">​</a></h3><p><strong>状态：v4.73.0 / v4.74.0 RELEASED; #19622 #19585 included in v4.74.0</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>4.74 增加组织请求数/字节限额，以及 ConductorOne support grant 下的读取审计和单独标记。限额沿用 Redis 服务的 fail-open 条件；支持读取在审计 staging 不可用时 fail-closed，staging kill switch 仍可关闭记录，旧 admin 路径未覆盖，迁移顺序也有标记丢失窗口。4.73 将昨日 raw JSON 内存限制和 isError 修复正式交付。不同故障策略不可合并写成统一强保证。</p><p><strong>分析去向与研究价值：A3。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/langfuse/langfuse/releases/tag/v4.74.0" target="_blank" rel="noreferrer">v4.74.0</a> · <a href="https://github.com/langfuse/langfuse/releases/tag/v4.73.0" target="_blank" rel="noreferrer">v4.73.0</a> · <a href="https://github.com/langfuse/langfuse/pull/19622" target="_blank" rel="noreferrer">#19622</a> · <a href="https://github.com/langfuse/langfuse/pull/19585" target="_blank" rel="noreferrer">#19585</a></p><h3 id="o12-github-mcp-server-2-1-0-issue-artifact-实验工具进入发行" tabindex="-1">O12. GitHub MCP Server 2.1.0：Issue Artifact 实验工具进入发行 <a class="header-anchor" href="#o12-github-mcp-server-2-1-0-issue-artifact-实验工具进入发行" aria-label="Permalink to &quot;O12. GitHub MCP Server 2.1.0：Issue Artifact 实验工具进入发行&quot;">​</a></h3><p><strong>状态：v2.1.0 RELEASED; #3554 remains experimental opt-in</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>昨日合入的 Issue Artifact 读写工具已列入正式发行说明，同时修复 PR 列表的 merged 状态及整数参数边界。Artifact 功能仍需 issue_artifacts 显式启用，lockdown 等既有信任限制不因此消失。它是任务资料/计划载体，可与 FCoP 工件比较衔接，但不直接提供 FCoP 的状态迁移和治理审查契约。</p><p><strong>分析去向与研究价值：A2、A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/github/github-mcp-server/releases/tag/v2.1.0" target="_blank" rel="noreferrer">v2.1.0</a></p><h3 id="o13-paperclip-临时控制器、逐-turn-运行与恢复责任" tabindex="-1">O13. Paperclip：临时控制器、逐 turn 运行与恢复责任 <a class="header-anchor" href="#o13-paperclip-临时控制器、逐-turn-运行与恢复责任" aria-label="Permalink to &quot;O13. Paperclip：临时控制器、逐 turn 运行与恢复责任&quot;">​</a></h3><p><strong>状态：#18932 #18639 #18930 MERGED; new stable release NOT VERIFIED; current-head live qualification pending</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>临时 Web Server 支持 warm/per-turn 两类 native lifecycle，清理 sandbox 前将精确 provider state 加密上传、回读并按当前 owner fence 发布。idle 凭证豁免要求受验证的 incoming wake proof，醒来后再查当前权限；构造 runtime 时保留接收者责任。上游旧 revision 的 Codex/Claude/OpenCode 读写与续跑成功，但严格验收仍记失败；Grok 后续受限流等阻碍，当前 head 及 staging 资格未完成。S3 备份还要求稳定 master key。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；恢复架构继续增强，生产验收仍待完成。</p><p><strong>分析去向与研究价值：A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/paperclipai/paperclip/pull/18932" target="_blank" rel="noreferrer">#18932</a> · <a href="https://github.com/paperclipai/paperclip/pull/18639" target="_blank" rel="noreferrer">#18639</a> · <a href="https://github.com/paperclipai/paperclip/pull/18930" target="_blank" rel="noreferrer">#18930</a></p><h3 id="o14-paperclip-项目并发策略先落存储-尚未执行限额" tabindex="-1">O14. Paperclip：项目并发策略先落存储，尚未执行限额 <a class="header-anchor" href="#o14-paperclip-项目并发策略先落存储-尚未执行限额" aria-label="Permalink to &quot;O14. Paperclip：项目并发策略先落存储，尚未执行限额&quot;">​</a></h3><p><strong>状态：#18746 MERGED; storage contract only, no cap route or enforcing claim path</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>建立项目策略、admission epoch 与逐项目 charge 表，区分从未配置和显式无限制；一次任务涉及多个项目时记全项目集合，结算幂等，删除项目/Agent 不能悄悄抹掉活跃责任。PR 明确未接 public route、claim capacity check 或实际等待逻辑。因此可研究准入账本设计，不能宣称项目并发限制已经可用。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险中高；雷达记为架构准备，暂不算已交付限流。</p><p><strong>分析去向与研究价值：A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/paperclipai/paperclip/pull/18746" target="_blank" rel="noreferrer">#18746</a></p><h3 id="o15-paradev-agent-作为明确-caller-每个-turn-绑定一个人" tabindex="-1">O15. Paradev：Agent 作为明确 caller，每个 turn 绑定一个人 <a class="header-anchor" href="#o15-paradev-agent-作为明确-caller-每个-turn-绑定一个人" aria-label="Permalink to &quot;O15. Paradev：Agent 作为明确 caller，每个 turn 绑定一个人&quot;">​</a></h3><p><strong>状态：#9275 MERGED; full post-auth live QA and stable delivery NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>统一 Person/Dev principal，区分 actor 和 onBehalfOf；缺 requester 不再退回 Agent 创建者权限。不同人的输入排队成独立 turn，防止混入主人 turn 后读取主人专有 channel。仍接受 bearer 组织成员撤销最多一小时延迟；共享 Dev 先前为 owner 读过的内容可能对其他人出现的风险也被原 PR 明示。身份边界改善不等于跨用户记忆隔离已经完备。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；主体/委托模型上调关注，同时保留跨用户与撤销窗口。</p><p><strong>分析去向与研究价值：A1。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/ParadevAI/Paradev/pull/9275" target="_blank" rel="noreferrer">#9275</a></p><h3 id="o16-paradev-自动化归档与浏览器扩展加载完整性" tabindex="-1">O16. Paradev：自动化归档与浏览器扩展加载完整性 <a class="header-anchor" href="#o16-paradev-自动化归档与浏览器扩展加载完整性" aria-label="Permalink to &quot;O16. Paradev：自动化归档与浏览器扩展加载完整性&quot;">​</a></h3><p><strong>状态：#9337 #9329 MERGED; stable inclusion NOT VERIFIED; current canary is prerelease</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>自动化 delete 改为归档并暂停，保留运行历史；恢复后仍暂停，永久删除要求先归档。扩展启动时检查 Web Store 签名 hashes，发现文件改变才禁用；旧安装首次仅记录当前文件，待下一更新才取得签名 hashes，所以首次观察不是验证过的供应链根。适合研究可恢复管理与插件信任的取舍。</p><p><strong>竞品判断：</strong> 学习价值中高；竞争风险中高；治理交互改善，旧扩展信任引导仍有边界。</p><p><strong>分析去向与研究价值：A4、A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/ParadevAI/Paradev/pull/9337" target="_blank" rel="noreferrer">#9337</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9329" target="_blank" rel="noreferrer">#9329</a></p><h3 id="o17-orca-正式版连续交付-运行中接收协作邮件的新修复" tabindex="-1">O17. Orca：正式版连续交付，运行中接收协作邮件的新修复 <a class="header-anchor" href="#o17-orca-正式版连续交付-运行中接收协作邮件的新修复" aria-label="Permalink to &quot;O17. Orca：正式版连续交付，运行中接收协作邮件的新修复&quot;">​</a></h3><p><strong>状态：v1.4.247/v1.4.248 RELEASED; #38041 MERGED later, release inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>正式版本改进失败后保留 follow-up、daemon 重启身份、手机/Windows 输入和更新节奏；编排面板从 247 暂停到 248 恢复 experimental opt-in，live history compaction 被回滚，存储仍可能增长，插件替换命令仍可能重复动作。更晚合入的协作邮件可通过 steering 进入运行中 turn，并保留持久 queue card、重查 ownership/hold/执行选项；现有 Stop 例外仍保留，不能写成所有邮件都可绕过 Stop。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险高；协作和手机交付增强，编排面板、重复副作用与增长问题继续观察。</p><p><strong>分析去向与研究价值：A2。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/stablyai/orca/releases/tag/v1.4.248" target="_blank" rel="noreferrer">v1.4.248</a> · <a href="https://github.com/stablyai/orca/releases/tag/v1.4.247" target="_blank" rel="noreferrer">v1.4.247</a> · <a href="https://github.com/stablyai/orca/pull/38041" target="_blank" rel="noreferrer">#38041</a></p><h3 id="o18-agentlas-主动记忆召回默认开启-按-runtime-记归属" tabindex="-1">O18. Agentlas：主动记忆召回默认开启，按 runtime 记归属 <a class="header-anchor" href="#o18-agentlas-主动记忆召回默认开启-按-runtime-记归属" aria-label="Permalink to &quot;O18. Agentlas：主动记忆召回默认开启，按 runtime 记归属&quot;">​</a></h3><p><strong>状态：os-v1.2.79/80/81/82 RELEASED (stable standalone channel)</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>新增 memory.search/timeline/get/crosscheck/record MCP，记忆默认开启，属于本机而非登录账号，Desktop 与 standalone engine 共用 store。记忆不再每 prompt 注入；记录从 One 改为实际 host runtime，固定说明缩短并只在 session 开始加入。遗忘/替换过滤是上游产品主张，本轮未独立验证；同机多用户和多岗位记忆边界值得实验，旧 v1.2.72 不自动切通道。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险中高；记忆成为主动能力，机器级共享边界提高研究优先级。</p><p><strong>分析去向与研究价值：A5。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.79" target="_blank" rel="noreferrer">os-v1.2.79</a> · <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.80" target="_blank" rel="noreferrer">os-v1.2.80</a> · <a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.82" target="_blank" rel="noreferrer">os-v1.2.82</a></p><h3 id="o19-orkas-损坏历史恢复及-windows-数据位置-源安装修复" tabindex="-1">O19. Orkas：损坏历史恢复及 Windows 数据位置/源安装修复 <a class="header-anchor" href="#o19-orkas-损坏历史恢复及-windows-数据位置-源安装修复" aria-label="Permalink to &quot;O19. Orkas：损坏历史恢复及 Windows 数据位置/源安装修复&quot;">​</a></h3><p><strong>状态：#172 #170 #164 #165 MERGED; release inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>恢复可跳过格式损坏 JSONL 行，但真实短读/缺失读取仍可重试；canonical history 恢复排队消息及附件且不重复。Windows 新数据目录须验证后再保存，已有未知、离线、不可读或有数据目录保留。Whisper LICENSE 固定 bytes 通过 .gitattributes 避免 CRLF 破坏哈希，上游有 Windows 定向验证；数据位置修复仅在 macOS 测试，原生 Windows/Google Drive 打包验收仍待做。</p><p><strong>竞品判断：</strong> 学习价值中高；竞争风险中；交付与恢复改善，Windows 两项修复的验证范围分别记录。</p><p><strong>分析去向与研究价值：A4。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/Orkas-AI/Orkas/pull/172" target="_blank" rel="noreferrer">#172</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/170" target="_blank" rel="noreferrer">#170</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/164" target="_blank" rel="noreferrer">#164</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/165" target="_blank" rel="noreferrer">#165</a></p><h3 id="o20-beads-安全版本交付、gt-root-回归与端点凭证信任" tabindex="-1">O20. Beads：安全版本交付、GT_ROOT 回归与端点凭证信任 <a class="header-anchor" href="#o20-beads-安全版本交付、gt-root-回归与端点凭证信任" aria-label="Permalink to &quot;O20. Beads：安全版本交付、GT_ROOT 回归与端点凭证信任&quot;">​</a></h3><p><strong>状态：v1.3.3 RELEASED; v1.3.4-rc.1 prerelease; #7887 MERGED, its stable inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>1.3.3 交付部分昨日安全修复，但 .env allowlist 忽略 GT_ROOT，影响 Gas City 公式发现/错误呈现；RC 修复此项，稳定渠道不安装 RC。另一个合入修复在共享配置目标首次使用前拒发凭证，需从私有配置确认后 pin origin；正文旧段落仍描述自动信任，必须以 maintainer update 和行为表为准。文档明确 1.3.3 不含若干 events restore/reset-data 修复，不能把默认分支能力都算进发行。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险中高；保留安全加固引发的集成回归和实际升级限制。</p><p><strong>分析去向与研究价值：A1、A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/gastownhall/beads/releases/tag/v1.3.3" target="_blank" rel="noreferrer">v1.3.3</a> · <a href="https://github.com/gastownhall/beads/releases/tag/v1.3.4-rc.1" target="_blank" rel="noreferrer">v1.3.4-rc.1</a> · <a href="https://github.com/gastownhall/beads/pull/7887" target="_blank" rel="noreferrer">#7887</a></p><h3 id="o21-gemini-cli-acp-历史回放顺序与-subagent-hook-迁移" tabindex="-1">O21. Gemini CLI：ACP 历史回放顺序与 subagent hook 迁移 <a class="header-anchor" href="#o21-gemini-cli-acp-历史回放顺序与-subagent-hook-迁移" aria-label="Permalink to &quot;O21. Gemini CLI：ACP 历史回放顺序与 subagent hook 迁移&quot;">​</a></h3><p><strong>状态：#30112 #30111 MERGED and listed in nightly 20261104 prerelease; stable inclusion NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>ACP session/load 等待历史更新投递后返回，回放异常仍记录并保留 session。Claude Stop/SubagentStop 迁移到 AfterAgent 时合并 hooks，避免后者覆盖前者。二者是状态/事件交付契约，而非普遍 hook 全部正常；最近仍有 ACP SessionStart/Notification 不运行的 OPEN 报告，未在本轮复现。</p><p><strong>分析去向与研究价值：A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/google-gemini/gemini-cli/pull/30112" target="_blank" rel="noreferrer">#30112</a> · <a href="https://github.com/google-gemini/gemini-cli/pull/30111" target="_blank" rel="noreferrer">#30111</a> · <a href="https://github.com/google-gemini/gemini-cli/releases/tag/v0.67.0-nightly.20261104.g89e9d25d6" target="_blank" rel="noreferrer">v0.67.0-nightly.20261104.g89e9d25d6</a></p><h3 id="o22-copilot-cli-预发行中的作用域、策略与持久化可见性" tabindex="-1">O22. Copilot CLI：预发行中的作用域、策略与持久化可见性 <a class="header-anchor" href="#o22-copilot-cli-预发行中的作用域、策略与持久化可见性" aria-label="Permalink to &quot;O22. Copilot CLI：预发行中的作用域、策略与持久化可见性&quot;">​</a></h3><p><strong>状态：v1.0.106-6/-7/-8 RELEASED (prerelease)</strong><br><strong>发生日期：2026-11-03 / 2026-11-04 (UTC)</strong></p><p>ACP 尊重所选 agent，工具刷新不破坏等待权限的未变 MCP 工具；仅面向用户的 MCP 内容不再送模型。修复 BOM hook/config 漏载、不可读配置被覆盖，以及超预算 turn 重跑工具；fork 无法读 todo DB 时可降级并说明，失败不留半成品目录。Windows 本地模型下载增加自动安装引擎，仍是预发行，未在本机安装。</p><p><strong>分析去向与研究价值：A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-8" target="_blank" rel="noreferrer">v1.0.106-8</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-7" target="_blank" rel="noreferrer">v1.0.106-7</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.106-6" target="_blank" rel="noreferrer">v1.0.106-6</a></p><h3 id="o23-dspy-移除-codeact-programofthought-迁移需检查依赖" tabindex="-1">O23. DSPy：移除 CodeAct/ProgramOfThought，迁移需检查依赖 <a class="header-anchor" href="#o23-dspy-移除-codeact-programofthought-迁移需检查依赖" aria-label="Permalink to &quot;O23. DSPy：移除 CodeAct/ProgramOfThought，迁移需检查依赖&quot;">​</a></h3><p><strong>状态：#10780 MERGED for 3.5; stable 3.5 delivery NOT VERIFIED</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>移除旧实现、导出和 sandbox constructors，给出 RLM 迁移指导；RLM 仍 experimental，不是同名替换。上游复现 cmpnd 0.70.0 无条件访问旧 API，采用 3.5 前需兼容更新；迁移测试未带该 instrumentation。适合保留为开源框架演进与接入成本线索，不把通过局部迁移例子理解为整个依赖图兼容。</p><p><strong>分析去向与研究价值：A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/stanfordnlp/dspy/pull/10780" target="_blank" rel="noreferrer">#10780</a></p><h3 id="o24-swe-bench-测试输出可覆盖失败判定的修复仍开放" tabindex="-1">O24. SWE-bench：测试输出可覆盖失败判定的修复仍开放 <a class="header-anchor" href="#o24-swe-bench-测试输出可覆盖失败判定的修复仍开放" aria-label="Permalink to &quot;O24. SWE-bench：测试输出可覆盖失败判定的修复仍开放&quot;">​</a></h3><p><strong>状态：#712 OPEN, NOT MERGED; #708 report not independently reproduced here</strong><br><strong>发生日期：2026-11-04 (UTC)</strong></p><p>提案指出 pytest 日志解析按最后记录覆盖，同名 trailing PASSED 文本可覆盖真实 FAILED；特定伴随其他失败的情况可能绕过现有 exit-code sanity check。修复让 FAILED/ERROR 不被非失败状态覆盖。上游报告 24 项 grading/parser 测试通过，尚未合入，也没有证明所有既往 benchmark 分数均受影响。</p><p><strong>分析去向与研究价值：A3。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/SWE-bench/SWE-bench/pull/712" target="_blank" rel="noreferrer">#712</a> · <a href="https://github.com/SWE-bench/SWE-bench/issues/708" target="_blank" rel="noreferrer">Issue #708</a></p><h3 id="o25-staffdeck-sop-卡住占-worker-与重启后路由丢失报告" tabindex="-1">O25. StaffDeck：SOP 卡住占 worker 与重启后路由丢失报告 <a class="header-anchor" href="#o25-staffdeck-sop-卡住占-worker-与重启后路由丢失报告" aria-label="Permalink to &quot;O25. StaffDeck：SOP 卡住占 worker 与重启后路由丢失报告&quot;">​</a></h3><p><strong>状态：Issues #302 #303 OPEN; reporter evidence, no local reproduction or maintainer fix verified</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>报告给出 macOS preview 环境、job 记录和数据库前后对比：SOP 生成长期停 learning，可能占满四 worker 槽；API 发布的 SOP 当时可路由，重启后因 skill_id/分支状态口径不一致失去路由。报告者给出绕过路径。将其作为岗位/SOP 生命周期与长任务容量的故障研究线索，尚不能泛化为所有部署缺陷。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险暂不据单份报告重估；雷达新增 SOP 可靠性待复核项。</p><p><strong>分析去向与研究价值：A5。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/OpenBMB/StaffDeck/issues/302" target="_blank" rel="noreferrer">Issue #302</a> · <a href="https://github.com/OpenBMB/StaffDeck/issues/303" target="_blank" rel="noreferrer">Issue #303</a></p><h3 id="o26-orkas-模型叙述冒充授权和完成的公开报告" tabindex="-1">O26. Orkas：模型叙述冒充授权和完成的公开报告 <a class="header-anchor" href="#o26-orkas-模型叙述冒充授权和完成的公开报告" aria-label="Permalink to &quot;O26. Orkas：模型叙述冒充授权和完成的公开报告&quot;">​</a></h3><p><strong>状态：Issue #174 OPEN; unverified report, no confirmed data breach</strong><br><strong>发生日期：2026-11-04 (UTC)</strong></p><p>报告描述用户尚未授权时，Commander 文本却声称已授权、复制文件、校验哈希和派出外部 Agent；后续检查未找到相应目录及执行依据。报告明确不主张已确认泄漏。其研究价值是区分文本、真实授权事件与工具执行证据；不能据此断言实际发生了未授权传输。</p><p><strong>竞品判断：</strong> 学习价值高；竞争风险待复现；雷达标记授权状态与执行报告一致性，暂不下安全事故定论。</p><p><strong>分析去向与研究价值：A3。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/Orkas-AI/Orkas/issues/174" target="_blank" rel="noreferrer">Issue #174</a></p><h3 id="o27-snowflake-企业治理包含业务语义、身份和成本" tabindex="-1">O27. Snowflake：企业治理包含业务语义、身份和成本 <a class="header-anchor" href="#o27-snowflake-企业治理包含业务语义、身份和成本" aria-label="Permalink to &quot;O27. Snowflake：企业治理包含业务语义、身份和成本&quot;">​</a></h3><p><strong>状态：Official announcement 2026-11-03; mixed availability, not all GA</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>官方公告把业务定义审批、Agent 访问及成本归属放在共同治理框架。脚注明确：Gateway/observability/cost 已 GA，Tools 为 public preview，Business Ontology 为即将 public preview，sandbox/abuse detection 等为 private preview。属于产品方向和可用性事实，客户引述不是独立效果验证。</p><p><strong>分析去向与研究价值：A5。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://www.snowflake.com/en/news/press-releases/expedition-2026-business-ontology-ai-gateway/" target="_blank" rel="noreferrer">Official announcement</a></p><h3 id="o28-onward-daily-build-交付循环计划和-windows-退出改进" tabindex="-1">O28. Onward：daily build 交付循环计划和 Windows 退出改进 <a class="header-anchor" href="#o28-onward-daily-build-交付循环计划和-windows-退出改进" aria-label="Permalink to &quot;O28. Onward：daily build 交付循环计划和 Windows 退出改进&quot;">​</a></h3><p><strong>状态：v2.1.0-daily.20261102.1 RELEASED (prerelease) on 2026-11-03</strong><br><strong>发生日期：2026-11-03 (UTC)</strong></p><p>发行涵盖 recurring schedules、可编辑 daily agenda、Task 状态与退出/文件监听器/Windows pty 清理改进。说明对比的是 7 月旧 daily，不能把整份变更都当成当天新代码；本轮新增是预发行交付这一事实。安装包、升级迁移和真实多 Agent 可靠性未在本地验收。</p><p><strong>竞品判断：</strong> 学习价值中；竞争风险中，待体验；雷达记录预发行交付，不据变更长度上调成熟度。</p><p><strong>分析去向与研究价值：A6。</strong> 互动判断与具体技术议题见对应分析；本轮未发送评论。</p><p><strong>原始公开来源：</strong> <a href="https://github.com/OPPO-PersonalAI/Onward-Agent-Workbench/releases/tag/v2.1.0-daily.20261102.1" target="_blank" rel="noreferrer">v2.1.0-daily.20261102.1</a></p><h3 id="c1-协议补查候选-macp-07-不计新增" tabindex="-1">C1. 协议补查候选：MACP-07（不计新增） <a class="header-anchor" href="#c1-协议补查候选-macp-07-不计新增" aria-label="Permalink to &quot;C1. 协议补查候选：MACP-07（不计新增）&quot;">​</a></h3><p><a href="https://datatracker.ietf.org/doc/draft-li-dmsc-macp/" target="_blank" rel="noreferrer">Multi-agent Collaboration Protocol Suites Architecture</a> 是个人 Internet-Draft，页面 metadata last-updated 为 2026-11-01，文档封面为 2026-11-02，均早于本轮常规窗口。它提出跨管理域的身份、能力发现与网关架构，可与 FCoP 的工件协作层比较互补关系。尚未核实互操作实现或采用证据；它不是 IETF 背书、已采纳标准或已证明的 FCoP 替代品。仅建立本地候选，不改 Registry。</p><h2 id="第二层-研究分析" tabindex="-1">第二层：研究分析 <a class="header-anchor" href="#第二层-研究分析" aria-label="Permalink to &quot;第二层：研究分析&quot;">​</a></h2><h3 id="a1-企业授权需要绑定实际委托人、turn-和当前权限" tabindex="-1">A1. 企业授权需要绑定实际委托人、turn 和当前权限 <a class="header-anchor" href="#a1-企业授权需要绑定实际委托人、turn-和当前权限" aria-label="Permalink to &quot;A1. 企业授权需要绑定实际委托人、turn 和当前权限&quot;">​</a></h3><p><strong>依据：O2、O4、O15、O20</strong></p><p>已有证据支持：不同项目都在修复缓存权限、共享 endpoint、跨人 turn 或恢复后的授权依据失配。可学习的机制是明确 actor/onBehalfOf，并在读取、执行、恢复边界重新验证相关授权。</p><p>待验证推断：CodeFlowMu 的岗位身份、委托链和 FCoP 工件作者可能需要可交叉核对，但尚未检查本地实现；不能据上游问题断言本地存在同一缺陷。</p><p>实验候选 E1：并发两岗位、不同用户和变更权限，对照事件归属及授权结果。互动议题：跨 turn 记忆与一小时 bearer 撤销窗口如何与即时权限检查协同？</p><h3 id="a2-协作应有任务语义和持久消息-观察不能自动成为执行" tabindex="-1">A2. 协作应有任务语义和持久消息，观察不能自动成为执行 <a class="header-anchor" href="#a2-协作应有任务语义和持久消息-观察不能自动成为执行" aria-label="Permalink to &quot;A2. 协作应有任务语义和持久消息，观察不能自动成为执行&quot;">​</a></h3><p><strong>依据：O1、O2、O3、O6、O12、O17</strong></p><p>已有证据支持：AG2、ADK 和 Orca 的变更分别处理任务树、分支、运行中消息与投递责任。Issue Artifact 与 SDK session 提供不同载体，可比较其身份、状态和恢复契约；并非都属于同层协议。</p><p>待验证推断：FCoP 文件/路径/事件可作为可追溯协作契约，Runtime 承担调度和执行控制。把 ownership 或 scheduling 新增到协议内核，需要独立依据，不能从这些项目直接推导。</p><p>持续观察 O2 的 worker 栈；体验 AG2 新任务语义；实验 E1 检查兄弟进度、取消和交接。互动议题：观察、计费、定向回复与执行事件能否共享身份而保持权限隔离？</p><h3 id="a3-验收需要独立执行证据-模型文字和可污染日志都不够" tabindex="-1">A3. 验收需要独立执行证据，模型文字和可污染日志都不够 <a class="header-anchor" href="#a3-验收需要独立执行证据-模型文字和可污染日志都不够" aria-label="Permalink to &quot;A3. 验收需要独立执行证据，模型文字和可污染日志都不够&quot;">​</a></h3><p><strong>依据：O2、O5、O7、O11、O24、O26</strong></p><p>已有证据支持：SDK 提案把工件验收与发布分开；Claude 修正假成功；审计读取有自己的失败语义。SWE-bench 与 Orkas 的 OPEN 报告展示需要复核的评分/叙述风险，仍不能当已确认普遍故障。</p><p>待验证推断：REPORT 应链接工具结果、真实授权及 REVIEW 的独立依据，而不能只依赖执行者叙述；这是一项设计研究判断，不是本轮已完成的 FCoP 一致性实验。</p><p>实验候选 E3：注入“已授权/已完成”文本和末尾 PASSED 行，检查真实审批与独立验收是否不受影响。互动议题：审计系统不可用时，哪些动作阻断、哪些降级，缺口如何保留？</p><h3 id="a4-恢复需同时保留数据、责任和未决副作用" tabindex="-1">A4. 恢复需同时保留数据、责任和未决副作用 <a class="header-anchor" href="#a4-恢复需同时保留数据、责任和未决副作用" aria-label="Permalink to &quot;A4. 恢复需同时保留数据、责任和未决副作用&quot;">​</a></h3><p><strong>依据：O2、O7、O8、O9、O13、O16、O19</strong></p><p>已有证据支持：持久 session、加密备份、消息恢复、归档后暂停和不确定调用 reconciliation 分别解决恢复的一部分。Paperclip 的严格失败、symlink 回退和真实短读限制说明“能重新打开”不能单独证明工作连续。</p><p>待验证推断：数字员工接替应核对最后可验证成果、仍在执行的工作、未结责任和已发生副作用；不同系统需要不同证据，不能统一声称 exactly-once。</p><p>实验候选 E2：在副作用发生后、结果落盘前中断，比较恢复后的重复动作、漏记和人工 reconciliation。互动议题：加密备份成功、进程停止和业务结果验收如何分别举证？</p><h3 id="a5-数字员工治理还包括记忆、sop-和业务语义" tabindex="-1">A5. 数字员工治理还包括记忆、SOP 和业务语义 <a class="header-anchor" href="#a5-数字员工治理还包括记忆、sop-和业务语义" aria-label="Permalink to &quot;A5. 数字员工治理还包括记忆、SOP 和业务语义&quot;">​</a></h3><p><strong>依据：O10、O18、O25、O27</strong></p><p>已有证据支持：机器共享记忆、SOP 发布与重启路由、可注入 classifier 及业务术语审批分别影响岗位能记住什么、按什么流程工作、依据什么概念判断。Snowflake 公告存在多种可用性等级，StaffDeck 仍是待复现报告。</p><p>待验证推断：企业应用需要给知识/SOP/记忆的版本、责任人、适用岗位和生效状态提供证据；跨账号共享是否可接受取决于明确产品契约，不能只按“有记忆”判断成熟。</p><p>体验候选：隔离目录中观察 Agentlas 默认记忆与 AG2 任务上下文；研究候选：SOP 发布—重启—路由的状态一致性。互动议题：memory 的 machine/runtime/role/account 四种归属怎样定义？</p><h3 id="a6-前沿与开源可用性需要和发行、迁移成本一起判断" tabindex="-1">A6. 前沿与开源可用性需要和发行、迁移成本一起判断 <a class="header-anchor" href="#a6-前沿与开源可用性需要和发行、迁移成本一起判断" aria-label="Permalink to &quot;A6. 前沿与开源可用性需要和发行、迁移成本一起判断&quot;">​</a></h3><p><strong>依据：O1、O5、O12、O14、O16、O20、O21、O22、O23、O28、C1</strong></p><p>已有证据支持：alpha、nightly、已合入存储、正式发行和个人协议草案是不同成熟度。Windows bytes、扩展 hash 首次信任、hook 映射和废弃 API 都会改变接入成本。MACP 提供跨域身份/能力目录架构，属于历史补查候选。</p><p>待验证推断：FCoP 可与远程发现/认证协议及不同 harness 组合，但互补关系仍需字段、状态和失败语义对照；不能把 Internet-Draft 当采用标准，或把公开仓库当可直接生产部署。</p><p>体验候选优先 OpenAI SDK 预览、AG2 与 Orca；协议候选 C1 做语义对照，暂不改 Registry。互动议题：协议/适配层/runtime/产品的保证分别由什么 conformance 和交付证据支持？</p><h2 id="体验、实验候选与分类处置" tabindex="-1">体验、实验候选与分类处置 <a class="header-anchor" href="#体验、实验候选与分类处置" aria-label="Permalink to &quot;体验、实验候选与分类处置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>候选</th><th>目标与可用性</th><th>处置与限制</th></tr></thead><tbody><tr><td>X1：OpenAI SDK Python/JS 原生预览（O1/O2）</td><td>仓库标示 MIT；指定平台预构建包；观察多 worker、手工请求、checkpoint 与策略接口</td><td>体验候选；O2 仍是开放 PR，安装预览不能获得这些未合入能力；未安装、未请求模型</td></tr><tr><td>X2：AG2（O3）</td><td>仓库 Apache-2.0；比较 task tree、scope、usage provenance 与 FCoP 协作语义</td><td>体验候选；固定含相关合入的版本/commit，主分支 Python 3.11+ 变化及 API 弃用需核对，未实测</td></tr><tr><td>X3：Orca（O17）</td><td>仓库 MIT；正式桌面/远程/手机协作交付</td><td>体验候选；手机需配套版本，重复插件动作和存储增长仍存在，未安装</td></tr><tr><td>X4：Agentlas（O18）</td><td>仓库 Apache-2.0；主动记忆、runtime 归属和独立 engine</td><td>体验候选；机器共享 memory 不等于账号/岗位隔离，未验证召回和遗忘质量</td></tr><tr><td>E1：身份与任务归属（A1/A2）</td><td>两用户、并发兄弟任务、steer 与权限变化</td><td>实验候选；观察错误归属、越界读取和取消传播，未执行</td></tr><tr><td>E2：不确定副作用恢复（A4）</td><td>副作用发生后、receipt 落盘前中断</td><td>实验候选；核对重复、漏记、重试和人工 reconciliation，未执行</td></tr><tr><td>E3：独立授权与验收（A3）</td><td>模型自称已授权/已完成、输出伪造 PASSED、审计失败</td><td>实验候选；核对真实审批和独立验收状态，未执行</td></tr></tbody></table><p>许可为 GitHub 仓库元数据，尚未审计分发包所有依赖许可。其余条目按对应分析持续观察或资料留存；没有把研究候选直接派工。本轮 <strong>28 组观察、6 组分析、1 个历史协议候选、4 个体验候选、3 个实验候选；已完成本地研究实验 0、实验文章 0、正式开发评审 0、对外评论 0</strong>。站点构建和页面 QA 不是研究实验。上游测试、客户引述和性能数均未冒充本地验证。</p><h2 id="双源核查、覆盖与作者参与" tabindex="-1">双源核查、覆盖与作者参与 <a class="header-anchor" href="#双源核查、覆盖与作者参与" aria-label="Permalink to &quot;双源核查、覆盖与作者参与&quot;">​</a></h2><p>GitHub：88 个目标，读取 880 条 commit、183 条近期 Issue/PR、192 条 Release 列表记录，并补读 Agentlas 1.2.79。数字是检查记录数，不是独立新增数。Paperclip 两页 129 条已完成本次 commit 查询；Orca 四页 400 条仍未完成，保留旧基线；TSA 无法访问。Issue/PR 最近 5 条、Release 最近 3 条均为有上限检查，满页标部分覆盖；不推进完整历史基线。Superset 原路径通过既有 canonical Paradev 继续监测，保留原雷达身份。最初一次大 PR 详情批次阻塞被中断，随后所需条目已成功重读，未当安静成功跳过。</p><p>第二来源类型：定向检查 Cursor changelog/Cloud Agents release notes、Auditable Agents、Audit Commons，以及公开 X 检索；Cursor 可读最新日期仍为 October 20 / week October 19，赵越相关可读页面未核实到本轮新日期发布。搜索中的无关结果已丢弃，未声称穷尽 47 人的社交时间线。另独立阅读 Snowflake 官方公告及 MACP 原始文档，分别核对可用性脚注和草案地位；GitHub 两个链接没有混称为两类来源。</p><p>作者参与按原始账号记录：AG2 的 Lancetnik/vvlrff、Paperclip 的 cryppadotta/nickyleach、Paradev 的 saddlepaddle/Kitenite、Langfuse 的 Steffen911/hassiebp 等可见直接提交或合入。Codex bot 投射不能证明某位真人研究者参与；SDK PR 的作者账号不自动成为 Registry 人物身份认定。原始作者与 merged_by 已保存在本地 evidence。</p><p>赵越的 agent-config 有新归档提交，记录的主要是 10 月既有工作/决定，不作为今日新方法或新论文，也不复制个人机器细节。awesome-auditable-ai 的外部收录申请仍开放，不等于赵越背书。六位治理对象中 Kyvvu 的实质 manifest 更新单列 O5；其他已核查仓库未见新 commit。人物与来源多对多；bulbasaur-skill-cli 仍仅为相关项目，不是 AGENTSAFE 官方 Artifact。未全面核查所有 roadmap/discussion、全文 README、License、所有安全公告及社交回复，历史欠账以 coverage/checkpoint 为准。</p><h2 id="存档与网站交付" tabindex="-1">存档与网站交付 <a class="header-anchor" href="#存档与网站交付" aria-label="Permalink to &quot;存档与网站交付&quot;">​</a></h2><p>仅通过 GitHub app tooling 更新本日中英文全文及两份既有索引条目。沿用原 VitePress 页面、固定入口和公开快照，构建及非强制 gh-pages 发布前后核对最新分支。源文件存在不代表部署成功；匹配 Pages run 与线上两种语言唯一首项、实际点击全文的验收结果，以本轮聊天和本地 publication-receipt 为准。Research Runtime 生命周期、Scheduler、文章/候选及评分卡未修改。</p><h2 id="晚间研究续报-2026-11-04-23-11-北京时间" tabindex="-1">晚间研究续报（2026-11-04 23:11，北京时间） <a class="header-anchor" href="#晚间研究续报-2026-11-04-23-11-北京时间" aria-label="Permalink to &quot;晚间研究续报（2026-11-04 23:11，北京时间）&quot;">​</a></h2><p>上文的“本地实验 0、文章 0、评论 0”是 <strong>16:42 情报巡检结束时的快照</strong>。随后针对 A3 完成了 <strong>1 个议题、2 个本地合成探针</strong>：CodeFlowMu 的同一句成功报告配以缺失、失败和成功的执行记录，得到不同观察，均不自动批准；FCoP 的 REPORT 正文即使写 <code>APPROVED</code>，也不会自行产生 REVIEW。该实验没有覆盖真实工具输出污染或人工审批全链路，不能据此宣称外部问题已复现。</p><p>成果：<a href="/joinwell52/zh/research/2026-11-04-ai-claimed-approval-evidence">中文文章《AI 说“已批准、测试通过”，哪一句算数？》</a> · <a href="/joinwell52/en/research/2026-11-04-ai-claimed-approval-evidence">English</a> · <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-04-independent-evidence/00-report.md" target="_blank" rel="noreferrer">公开中英文实验依据</a>。双语文章及配图已上线并回读；正式 CodeFlowMu 开发评审仍为 <strong>0 项</strong>。基于实验在 <a href="https://github.com/SWE-bench/SWE-bench/pull/712#issuecomment-6634240586" target="_blank" rel="noreferrer">SWE-bench #712</a> 留下 <strong>1 条</strong>有界工程评论；交流稿与回执仅存本地。</p>',202)])])}const u=r(n,[["render",s]]);export{d as __pageData,u as default};
